#: `RISHI_LITERT_GPU=0` forces CPU when GPU/NPU init fails.
_special_build = re.compile(r'(-(gpu|web|npu)|_)[^/]*\.litertlm$')
def _portable(p):
    "Whether `p` is portable across LiteRT backends."
    return bool(p) and not _special_build.search(str(p))

LITERT_GPU = str2bool(os.getenv('RISHI_LITERT_GPU', '1').lower())
def _litertlm(fs):
    "Select a portable `.litertlm`, excluding web builds."
    return first(sorted([p for p in fs if p.endswith('.litertlm') and 'web' not in p], key=lambda p: not _portable(p)))

def cached_model(model_id):
    "Return the local `.litertlm` path from the Hugging Face cache without touching the network, else None."
    return _litertlm(hub_files(model_id))

def get_model(model_id, model_path=None):
    "Return a local `.litertlm` path: `model_path`, else HF cache, else download."
    if model_path and Path(model_path).exists(): return model_path
    hit = cached_model(model_id)
    if _portable(hit): return hit
    try: fn = _litertlm(list_repo_files(model_id))
    except Exception:
        if hit: return hit
        raise
    if not fn and not hit: raise FileNotFoundError(f"No .litertlm file found for {model_id}")
    return hf_hub_download(model_id, fn) if _portable(fn) or not hit else hit

_cached_model, _get_model = cached_model, get_model

def _is_gpu(be):
    "Whether `be` is litert's GPU backend, as an instance or as the class."
    return isinstance(be, Backend.GPU) or (isinstance(be, type) and issubclass(be, Backend.GPU))

#: Header names of the encoders a multimodal engine can be given a backend for.
_encoders = {'vision_backend': b'tf_lite_vision_encoder', 'audio_backend': b'tf_lite_audio_encoder'}
def _mm_kw(mod, vbe, abe):
    "Return backends for encoders present in `mod`."
    try:
        with open(mod, 'rb') as f: head = f.read(1<<16)
    except OSError: head = b''.join(_encoders.values())
    out = {}
    for k, v in (('vision_backend', vbe), ('audio_backend', abe)):
        if _encoders[k] in head: out[k] = ifnone(v, Backend.CPU())
        elif v is not None: warnings.warn(f"{Path(mod).name} carries no {k.split('_')[0]} encoder; building without one.")
    return out

def _gpu_act(be, kw):
    "Use float32 GPU activations unless the caller chose a dtype."
    return {} if 'activation_data_type' in kw or not _is_gpu(be) else {'activation_data_type': ActivationDataType.FLOAT32}

def _merge_chunks(chunks):
    "Reconstruct an assistant response dict (text + thinking) from streamed litert chunks."
    text, th = ''.join(resp_text(c) for c in chunks), ''.join(thought(c) for c in chunks)
    r = {'role': 'assistant', 'content': [{'type': 'text', 'text': text}]}
    if th: r['channels'] = {'thought': th}
    return Resp(r)

#: How litert says the window is full: before litert-lm 0.19, and from it with history plus input, and with one input alone.
#: 'available state entries' also covers 'Chosen prefill work group size exceeds available state entries (82)'.
_litert_full = ('available state entries', 'not enough space left in the context window', 'input token ids are too long')
def _litert_too_long(e):
    "Whether litert refused one input for being longer than the whole window, which evicting history cannot fix."
    return 'input token ids are too long' in str(e).lower()

_dflt_cbs = [_HistoryCallback, _UsageCallback, _ToolReminderCallback, SlidingWindowCallback]

class LitertChat(Chat):
    "A `Chat` that runs a `.litertlm` model inside this process through Google's LiteRT-LM."
    _runtime = 'litert'
    _dflt_cbs = _dflt_cbs
    mk_content, mk_msg, mk_msgs = staticmethod(_mk_content), staticmethod(_mk_msg), staticmethod(_mk_msgs)

    @staticmethod
    def fmt2hist(msgs):
        "litert-native messages -> canonical rishi history dicts."
        return [_fmt2hist(m) for m in listify(msgs)]
    @staticmethod
    def hist2fmt(msgs):
        "Canonical rishi history dicts -> litert `Message`s for the engine."
        return [_hist2fmt1(m) for m in listify(msgs)]

    @classmethod
    def create_engine(cls, model_id=gemma4_e2b, model_path=None, be=None, vbe=None, abe=None,
                      multimodal=True, cache_dir=None, enable_speculative_decoding=None, **kw):
        'Build a LiteRT-LM `Engine`, trying the GPU first and falling back to the CPU unless a backend is given.'
        be, vbe, abe = kw.pop('backend', be), kw.pop('vision_backend', vbe), kw.pop('audio_backend', abe)
        if cache_dir: Path(cache_dir).mkdir(parents=True, exist_ok=True)
        mod = get_model(model_id, model_path)
        def _mk(b):
            mm = _mm_kw(mod, vbe, abe) if multimodal else {}
            return Engine(mod, backend=b, cache_dir=cache_dir or '',
                          enable_speculative_decoding=enable_speculative_decoding, **_gpu_act(b, kw), **mm, **kw)
        if be is not None: return _mk(be)
        if LITERT_GPU:
            try: return _mk(Backend.GPU())
            except Exception as e:
                warnings.warn(f'litert GPU backend unavailable ({type(e).__name__}: {e}) - falling back to the '
                              'CPU. Set RISHI_LITERT_GPU=0 to stop asking for it.')
        return _mk(Backend.CPU())

    #: litert takes the window when it builds the engine, and nests it inside `eng_kw`
    _opt_map = {'ctx': 'eng_kw.max_num_tokens'}
    _opt_skip = ('effort', 'tool_mode', 'api_key', 'base_url')   # nothing local takes these

    def __init__(self, model=None, *, runtime=None, model_path=None, opts=None,
                 engine=None,        # an engine to share instead of building one
                 backend=None,       # litert's hardware backend: `Backend.CPU()` or `Backend.GPU()`
                 multimodal=True,    # build the vision and audio backends too
                 cache_dir=None, enable_speculative_decoding=None,
                 eng_kw=None,        # passed to `create_engine` verbatim
                 filter_think=True,  # keep thought tokens out of the KV cache
                 sampler_config=None,  # a litert `SamplerConfig`, instead of the portable sampling options
                 constrain=None,     # constrained decoding; default is on when there are tools
                 conv_kw=None,       # passed to `create_conversation` verbatim
                 **kw):              # portable options; see `urai.ChatOpts`
        o = ChatOpts.create(opts, **kw)
        if o.parallel_tools: raise NotImplementedError(
            "litert runs its tool loop inside the engine, so it can't dispatch calls in parallel; "
            "use runtime='llama' (or 'mlx') for parallel_tools=True.")
        model_id, model_path = rishi.core.split_model_path(model, model_path)
        self._stack, self._conv_stack = ExitStack(), ExitStack()
        ekw = dict(eng_kw or {})
        if o.ctx: ekw.setdefault('max_num_tokens', o.ctx)
        self._own_engine = engine is None
        if self._own_engine:
            engine = self.create_engine(model_id or gemma4_e2b, model_path, backend,
                multimodal=multimodal, cache_dir=cache_dir,
                enable_speculative_decoding=enable_speculative_decoding, **ekw)
            self.engine = self._stack.enter_context(engine)
        else: self.engine = engine
        # the system prompt is kept apart from `hist` and re-applied on every rebuild, so eviction
        # can never drop it: it is the anchor a sliding window is supposed to preserve
        self._sys_pre = [{'role': 'system', 'content': o.sp}] if o.sp else []
        if sampler_config is None and any(x is not None for x in (o.temp, o.top_k, o.top_p, o.seed)):
            sampler_config = SamplerConfig(temperature=o.temp, top_k=o.top_k, top_p=o.top_p, seed=o.seed)
        cvk = dict(sampler_config=sampler_config, max_output_tokens=o.max_output_tokens or None,
                   **(conv_kw or {}))
        if o.think: cvk['extra_context'] = {**cvk.get('extra_context', {}), 'enable_thinking': True}
        if filter_think: cvk['filter_channel_content_from_kv_cache'] = True
        if (legacy := cvk.pop('enable_constrained_decoding', None)) is not None:
            warnings.warn("enable_constrained_decoding was litert's own name for this and is "
                          'not accepted any more; pass constrain=True/False to rishi instead.',
                          DeprecationWarning, stacklevel=2)
            if constrain is None: constrain = bool(legacy)
        self._constrain = constrain
        self._conv_kw, self.tools, self.conv = cvk, L(o.tools), None
        self.tool_handler, self._hold = ChatToolHandler(self), EngineHold(self)
        self._litert_turn_reset()
        self._mk_conv(self._sys_pre + [_to_litert_msg(m) for m in listify(o.messages)])
        self.ctx_limit = o.ctx or None
        self._setup(model, o)

    def _constrained(self):
        "The `constrained_decoding_config` to build with, or `None`. Default is on when there are tools."
        if 'constrained_decoding_config' in self._conv_kw: return None
        want = bool(self.tools) if self._constrain is None else bool(self._constrain)
        return ConstrainedDecodingConfig(enable=True) if want else None

    def _mk_conv(self, messages=None):
        "Build the conversation from `messages`, releasing any current one first."
        self._conv_stack.close()
        self._conv_stack = ExitStack()
        kw = dict(self._conv_kw)
        if (cd := self._constrained()) is not None: kw['constrained_decoding_config'] = cd
        self.conv = self._conv_stack.enter_context(self.engine.create_conversation(
            messages=messages or None, tools=_approved_tools(self.tools, self.tool_handler) or None,
            tool_event_handler=self.tool_handler, **kw))
        return self.conv

    def _set_sp(self, sp):
        "The system prompt lives outside `hist` here, so `reconfigure` has to replace it explicitly."
        self._sys_pre = [{'role': 'system', 'content': sp}] if sp else []

    def _recreate_conv(self):
        "Rebuild the `Conversation` from the current (possibly evicted) `hist`, re-applying the system prompt."
        self._mk_conv(self._sys_pre + [_to_litert_msg(m) for m in self.hist])

    def recover_context(self, err, **kw):
        "Recover a full context by evicting the middle of history and sending the current message again."
        r, = self._litert_evict_retry(self._litert_send_once, kw, err)
        return r

    def _litert_turn_start(self):
        "Index in `hist` of this turn's recorded outgoing message, the last user entry, else the end of `hist`."
        h = self.hist
        return next((i for i in range(len(h)-1, -1, -1) if h[i]['role'] == 'user'), len(h)) if self._turn_msg_recorded else len(h)

    def _litert_drop_turn(self):
        "Forget a turn the window could not take, and rebuild `conv` from the history before it: after a full-window error litert's conversation fails every later send ('INTERNAL: Task failed with state: 7')."
        del self.hist[self._litert_turn_start():]
        self._turn_msg_recorded = False
        self._recreate_conv()
        self._tc0 = self.conv.token_count

    def _litert_evict(self, err, keep_first=2, keep_last=6):
        "Evict the middle of `hist` for a turn that filled the window, rebuild `conv`, and return how many messages left. Raises `ContextWindowExceededError` when nothing can leave."
        h = self.hist
        # A recorded outgoing message is the last user entry. The engine will rerun the tool rounds
        # that follow it, so they leave the history and the message is sent again, not preloaded.
        cut = self._litert_turn_start()
        kept, dropped = evict_middle(h[:cut], keep_first, keep_last)
        # too short to have a middle: the current message comes first, so all earlier history leaves (the system prompt stays)
        if not dropped: kept, dropped = [], h[:cut]
        partial = max(len(h) - cut - 1, 0)
        if not dropped and not partial:
            raise ContextWindowExceededError(f"context window full and nothing left to evict: {err}") from err
        h[:] = kept + h[cut:cut+1]
        self.evicted = getattr(self, 'evicted', 0) + len(dropped) + partial
        self._mk_conv(self._sys_pre + [_to_litert_msg(m) for m in kept])
        self._tc0 = self.conv.token_count            # the rebuilt cache is a new baseline for usage
        return len(dropped)

    # One turn can be several model steps inside one litert send: litert runs the tool loop itself, so
    # text, a tool call, the tool's result prefilled, and more text all come from one `send_message_async`.
    # A step is the model's work between two tool rounds. The window can fill in any step's prefill.
    def _litert_turn_reset(self):
        "Forget the step state of the last turn: no tool round yet, nothing yielded in this step."
        self._litert_round, self._litert_rounds, self._litert_step_n, self._litert_step_text = None, 0, 0, []

    def _litert_round_tc(self):
        "The conversation's token count, or `None` when litert cannot say."
        try: return self.conv.token_count
        except Exception: return None

    def _litert_round_start(self):
        "Start the record of a tool round: where its calls begin in `hist`, the token count that tells its calls from the next round's, the step's text, and the results litert will send."
        tc = self._litert_round_tc()
        self._litert_round = {'at': len(self.hist), 'tc': tc, 'text': ''.join(self._litert_step_text),
                              'parts': None if tc is None else []}   # `None`: this round's results cannot be told from another's
        self._litert_rounds += 1
        return self._litert_round

    def _litert_round_result(self, name, resp):
        "Record one result as litert sends it, and start the next step, which has yielded nothing yet."
        if (rd := self._litert_round) is not None and rd['parts'] is not None:
            rd['parts'].append({'type': 'tool_response', 'name': name, 'response': resp})
        self._litert_step_n, self._litert_step_text = 0, []

    def _litert_evict_step(self, err, rd, keep_first=2, keep_last=6):
        "For a step after tool round `rd` that filled the window: evict history from before the turn, else the turn's earlier tool rounds, rebuild `conv` up to the round's results, and return how many messages left and the result to send again. Tools do not run again."
        if not rd['parts']: raise ContextWindowExceededError(
            f"context window filled after a tool round whose results could not be told from another round's, "
            f"so the step was not sent again: {err}") from err
        h, cut, at = self.hist, self._litert_turn_start(), rd['at']
        kept, dropped = evict_middle(h[:cut], keep_first, keep_last)
        if not dropped: kept, dropped = [], h[:cut]
        if dropped: h[:] = kept + h[cut:]
        elif at > cut + 1: dropped, h[:] = h[cut+1:at], h[:cut+1] + h[at:]   # nothing before the turn: its earlier tool rounds leave
        else: raise ContextWindowExceededError(
            f"context window full and nothing left to evict: the turn's message and its latest tool round fill it alone: {err}") from err
        rd['at'], rd['tc'] = at - len(dropped), -1   # a rebuilt conversation counts tokens afresh
        self.evicted = getattr(self, 'evicted', 0) + len(dropped)
        # the round's calls as litert's conversation held them: one model message with the step's text and every call
        calls = {'role': 'assistant', 'content': rd['text'],
                 'tool_calls': [tc for m in h[rd['at']:] if m['role'] == 'assistant' for tc in m.get('tool_calls') or []]}
        self._mk_conv(self._sys_pre + [_to_litert_msg(m) for m in h[:rd['at']] + [calls]])
        self._tc0 = self.conv.token_count
        # the results go as one tool message, one part per call: litert-lm 0.19's own shape, and 0.16's for a single call
        return len(dropped), {'role': 'tool', 'content': list(rd['parts'])}

    def _litert_send_once(self, turn, msg=None):
        "Yield litert's whole reply to `msg` (default `turn_msg`) as one item, so `_send` goes through `_litert_evict_retry` as `_stream` does."
        yield self.conv.send_message(ifnone(msg, self.turn_msg), **self._turn_kw(turn))

    def _litert_stream_once(self, turn, msg=None):
        "Yield litert's chunks for `msg` (default `turn_msg`), cancelling the native generation if the stream stops early."
        it, done = self.conv.send_message_async(ifnone(msg, self.turn_msg), **self._turn_kw(turn)), False
        try:
            for o in it: yield o
            done = True
        finally:
            if not done: self.conv.cancel_process()   # a stream closed early would otherwise keep generating natively
            it.close()

    def _litert_try_once(self, call, turn, msg=None):
        "Yield what `call(turn, msg)` yields. Return litert's full-window error if it came before the step that filled the window yielded anything; raise `ContextWindowExceededError` if that step had yielded, or if the input alone is longer than the window."
        self._litert_step_n, g = 0, call(turn, msg)
        try:
            for o in g:
                self._litert_step_n += 1; self._litert_step_text.append(resp_text(o) or '')
                yield o
        except RuntimeError as e:
            if isinstance(e, ContextWindowExceededError): raise
            if not (is_ctx_error(self, e) or any(m in str(e).lower() for m in _litert_full)): raise
            if _litert_too_long(e): raise ContextWindowExceededError(
                f"this message alone is longer than the {f'{self.ctx_limit}-token ' if self.ctx_limit else ''}context window, "
                f"so evicting history cannot make room for it; it was not sent: {e}") from e
            if (n := self._litert_step_n): raise ContextWindowExceededError(
                f"context window filled after {n} chunks of this step's reply were already yielded, "
                f"so the step was not sent again: {e}") from e
            return e
        finally: g.close()

    def _litert_evict_retry(self, call, turn, err=None, keep_first=2, keep_last=6):
        "Run one turn through `call` (`_litert_send_once` or `_litert_stream_once`). If a step fills the window before it yielded anything, evict and run that step once more: the first step resends the turn message, a later one resends only the last tool round's results, so earlier steps are not repeated and tools do not run again. Given `err`, the window already filled, so start by evicting. A turn that still fails on the window leaves `hist` and `conv` as they were before it, so later turns work."
        try:
            if err is None:
                err = yield from self._litert_try_once(call, turn)
                if err is None: return
            while True:
                step, rd = self._litert_rounds, self._litert_round
                n, msg = (self._litert_evict(err, keep_first, keep_last), None) if rd is None else self._litert_evict_step(err, rd, keep_first, keep_last)
                if (again := (yield from self._litert_try_once(call, turn, msg))) is None: return
                if self._litert_rounds == step:
                    raise ContextWindowExceededError(f"could not recover after evicting {n} messages: {err}") from again
                err = again   # a later step filled the window: it gets its own retry
        except ContextWindowExceededError:
            self._litert_drop_turn(); raise

    @property
    def token_count(self): return self.conv.token_count
    @property
    def cached_tokens(self):
        "Tokens already resident in this conversation's KV cache and reusable by the next turn."
        return self.conv.token_count
    def cancel(self):
        "Cancel the in-flight generation, and set the flag the shared loop reads."
        super().cancel()
        if self.conv is not None: self.conv.cancel_process()
        return True
    def count_tokens(self, text):
        "Number of tokens in `text` per the engine tokenizer."
        return len(self.engine.tokenize(text))
    def _ck_fits(self, prompt, sp=''):
        "Refuse a prompt that cannot fit in `ctx_limit`, with both figures, before litert returns null."
        if not self.ctx_limit: return
        n = self.count_tokens(sp + prompt)
        if n > self.ctx_limit: raise ContextWindowExceededError(f"prompt is {n} tokens, over the {self.ctx_limit}-token context window")
    def render(self, msg):
        "The exact templated string litert will send for `msg`."
        return self.conv.render_message_to_string(_mk_msg(msg))
    def _turn_kw(self, turn):
        "What litert's `send_message` takes from this turn's generation options."
        t = self.map_opts(turn); t.pop('eng_kw', None)   # the window was fixed when the engine built
        return {'max_output_tokens': t.get('max_output_tokens')}

    def _send(self, msg, **kw):
        'Send one message through the callback pipeline, evicting and retrying once if the window fills.'
        self.turn_msg = _mk_msg(msg)
        self._turn_msg_recorded = False
        self._litert_turn_reset()
        for _ in run_cbs(self, 'before_send'): pass
        self._tc0 = self.conv.token_count      # after the callbacks: one may have rebuilt `conv`
        with self._hold: r, = self._litert_evict_retry(self._litert_send_once, kw)
        self.turn_res = Resp(r)
        for _ in run_cbs(self, 'after_response'): pass
        return self.turn_res
    def _stream(self, msg, cbs=None, **kw):
        'Stream a turn as markdown chunks, evicting and retrying once if the window fills before the first chunk. Per-call `cbs` live only for this turn.'
        added = self.add_cbs(cbs); prev = getattr(self, '_streaming', False); self._streaming = True
        try:
            self.turn_msg = _mk_msg(msg)
            self._turn_msg_recorded = False
            self._litert_turn_reset()
            for _ in run_cbs(self, 'before_send'): pass
            self._tc0 = self.conv.token_count   # after the callbacks: one may have rebuilt `conv`
            fmt, chunks = StreamFormatter(), []
            with self._hold, closing(self._litert_evict_retry(self._litert_stream_once, kw)) as rs:   # a caller closing early reaches `_litert_stream_once`'s cancel
                for o in rs:
                    chunks.append((self._litert_rounds, o)); yield self._emit(o, fmt)
            # the reply is the last step's, as from `_send`: text before a tool call already sits beside the call in `hist`
            self.turn_res = _merge_chunks([o for r, o in chunks if r == self._litert_rounds])
            yield from run_cbs(self, 'after_response')
            return self.turn_res   # stream's final Resp, captured by SaveReturn / AsyncChat `.value`
        finally: self._streaming = prev; self.remove_cbs(added)
    def _oneshot(self, prompt, sp='', think=None, max_tokens=None):
        """Stateless one-shot completion text via a throwaway conversation."""
        self._ck_fits(prompt, sp)
        kw = {'extra_context': {'enable_thinking': True}} if think else {}
        if max_tokens is not None: kw['max_output_tokens'] = int(max_tokens)
        pre = [{'role': 'system', 'content': sp}] if sp else None
        with self.engine.create_conversation(messages=pre, **kw) as conv, EngineHold(self):
            return resp_text(conv.send_message(prompt))
    def _structured_call(self, prompt, schema, sp):
        "Forced tool call, falling back to parsing a JSON reply when the model answers in prose."
        self._ck_fits(prompt, sp)
        pre = [{'role': 'system', 'content': sp}] if sp else None
        with self.engine.create_conversation(messages=pre, tools=[schema], automatic_tool_calling=False) as conv, EngineHold(self):
            r = conv.send_message(prompt)
        if tcs := r.get('tool_calls'): return tcs[0].get('function', {}).get('arguments', {})
        try: return json.loads(extract_fence(resp_text(r), 'json'))
        except (json.JSONDecodeError, TypeError) as e: raise ValueError(f"model neither called the tool nor returned JSON; reply: {resp_text(r)[:200]!r}") from e
    def close(self):
        "Release this chat's conversation and, only when owned, its engine (idempotent)."
        if getattr(self, '_conv_stack', None) is not None: self._conv_stack.close(); self._conv_stack = None
        if getattr(self, '_own_engine', False) and getattr(self, '_stack', None) is not None:
            self._stack.close()
        self._stack = None
        self.conv = None


